def apply(rel, txt):
    import hashlib
    if rel != 'inc/designer.php':
        raise SystemExit('myplan_653: no hunk on ' + rel)
    for a, b in HUNKS:
        if txt.count(a) != 1:
            raise SystemExit('myplan_653: FATAL anchor x%d in %s: %r' % (txt.count(a), rel, a[:60]))
        txt = txt.replace(a, b)
    if hashlib.md5(txt.encode('utf-8')).hexdigest() != NEW_MD5:
        raise SystemExit('myplan_653: FATAL the file is not the reviewed text after the hunks')
    print('[hunk] %s: %d hunk(s), the result is the reviewed text' % (rel, len(HUNKS)))
    return txt


def apply_main(txt):
    """the module list stays as the previous release left it"""
    if txt.count(MAIN_LIST) != 1 or "'designer'" not in MAIN_LIST:
        raise SystemExit('myplan_653: FATAL: the live module list tail is not the one the previous release left')
    if txt.count(BUY) != 1 or txt.count("'buying-hub'") != 1:
        raise SystemExit('myplan_653: FATAL: buying-hub is not once before i18n in the live nadlan-config.php; read it before releasing')
    print("[hunk] nadlan-config.php: no module change ('designer' loaded, proven)")
    return txt
